import styles from './styles.module.css';

export class CodeBlockIdentity {
  constructor(
    readonly language: string | undefined,
    readonly className: string,
  ) {}
}

export function useCodeBlockHighlightInputs(props: {
  language: string | undefined;
  className: string;
  metastring: string | undefined;
  title: string | undefined;
  showLineNumbers: boolean | undefined;
}): ReturnType<typeof useCodeBlockMeta> & {identity: CodeBlockIdentity} {
  const rest = useCodeBlockMeta({
    metastring: props.metastring,
    title: props.title,
    showLineNumbers: props.showLineNumbers,
  });
  return {
    identity: new CodeBlockIdentity(props.language, props.className),
    ...rest,
  };
}

export default function CodeBlockLine({
  line,
  classNames,
  showLineNumbers,
  getLineProps,
  getTokenProps,
}: Props): JSX.Element {
  if (line.length === 1 && line[0]!.content === '\n') {
    line[0]!.content = '';
  }

  const lineProps = getLineProps({
    line,
    className: clsx(classNames, showLineNumbers && styles.codeLine),
  });

  const lineTokens = line.map((token, key) => (
    <span key={key} {...getTokenProps({token, key})} />
  ));

  return (
    <span {...lineProps}>
      {showLineNumbers ? (
        <>
          <span className={styles.codeLineNumber} />
          <span className={styles.codeLineContent}>{lineTokens}</span>
        </>
      ) : (
        lineTokens
      )}
      <br />
    </span>
  );
